1|// Skin-matched drawing shown while the picture loads. The parent keeps
2|// a frozen still mounted under the image until it loads, so the drawing
3|// stops the instant the card turns ready.
4|"use client";
5|
6|import { useCallback, useEffect, useId, useMemo, useRef, useState } from "react";
7|import type { PictureSkin } from "./picture-skin";
8|import { DRAW_NOTE, DRAW_STATUS, stillStrokes, strokesForSkin } from "./picture-draw-paths";
9|import { Paper, Tool } from "./picture-draw-tools";
10|
11|function useReducedMotion(): boolean {
12|  // Start still so server HTML matches; the real value applies on mount.
13|  const [reduced, setReduced] = useState(true);
14|  useEffect(() => {
15|    if (typeof window.matchMedia !== "function") return;
16|    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
17|    setReduced(mq.matches);
18|    const onChange = () => setReduced(mq.matches);
19|    mq.addEventListener("change", onChange);
20|    return () => mq.removeEventListener("change", onChange);
21|  }, []);
22|  return reduced;
23|}
24|
25|interface FlatStroke {
26|  d: string;
27|  stroke: string;
28|  width: number;
29|  opacity: number;
30|  fill?: string;
31|  blurred?: boolean;
32|}
33|
34|export function usePictureLoaded(url: string) {
35|  // True once the ready image has actually loaded. The url sits next to
36|  // the flag so a cached ready-to-ready swap resets in the same render,
37|  // never flashing the new image as revealed.
