1|// Stand-in sketch paths for the drawing slot: the prototype's Oz
2|// house/cyclone scene. Pure data, no DOM. Seeded per layer so every
3|// replay draws the same picture.
4|import type { PictureSkin } from "./picture-skin";
5|
6|import {
7|  C,
8|  CONTOURS,
9|  OVAL,
10|  OVAL_INNER,
11|  R,
12|  blobPath,
13|  clip,
14|  hatch,
15|  ovalPts,
16|  rng,
17|  segD,
18|  zigzag,
19|  type DrawStroke,
20|  type Pt,
21|} from "./picture-draw-geom";
22|import { extraLayer, extraStill } from "./picture-draw-extra";
23|
24|export type { DrawStroke } from "./picture-draw-geom";
25|
26|const INK = "#2A241C";
27|const BLUE = "#0866FF";
28|
29|function engravingLayer(layer: number): DrawStroke[] {
30|  const r = rng(3 + layer);
31|  if (layer === 0) {
32|    const out: DrawStroke[] = [
33|      { d: OVAL, stroke: INK, width: 1.1, opacity: 1 },
34|      { d: OVAL_INNER, stroke: INK, width: 0.5, opacity: 1 },
35|    ];
36|    for (const k of CONTOURS) {
37|      out.push({ d: C[k], stroke: INK, width: k === "funnel" ? 1.2 : 0.9, opacity: 1 });
38|    }
39|    return out;
40|  }
41|  const oval = ovalPts();
42|  const polys: [Pt[], number, number][] = [
43|    [R.sky, layer % 2 ? -40 : 40, 6 + layer],
44|    [R.ground, layer % 2 ? 20 : -20, 5 + layer],
45|    [R.roof, layer % 2 ? 60 : -60, 4 + layer],
46|  ];
47|  const out: DrawStroke[] = [];
48|  for (const [poly, deg, gap] of polys) {
49|    for (const s of hatch(poly, deg, gap, 1, r)) {
50|      const a = s[0];
51|      const b = s[1];
52|      if (!a || !b) continue;
53|      const len = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1;
54|      const inside = clip(oval, a, [(b[0] - a[0]) / len, (b[1] - a[1]) / len]);
55|      if (inside) out.push({ d: segD(inside, 3), stroke: INK, width: 0.45, opacity: 0.7 });
56|    }
57|  }
58|  return out;
59|}
60|
61|const SPOTS: [number, number, string, number][] = [
62|  [70, 70, "#9FC4FF", 46], [160, 56, "#C9DDF7", 52], [232, 96, "#7FB0FF", 40],
63|  [262, 180, "#9AA3B5", 30], [256, 250, "#9AA3B5", 24], [150, 190, "#C9785A", 36],
64|  [150, 246, "#E6C27A", 44], [110, 250, "#E6C27A", 30], [60, 262, "#6FA0E8", 18],
65|  [90, 318, "#B9C98A", 48], [200, 322, "#B9C98A", 52], [150, 350, "#CFD9A8", 40],
66|];
67|
68|function watercolorLayer(layer: number): DrawStroke[] {
69|  const r = rng(11 + layer);
70|  const spots = layer ? [...SPOTS].sort(() => r() - 0.5) : SPOTS;
71|  return spots.map(([x, y, c, rad]) => {
72|    const jx = x + (r() - 0.5) * 24 * layer;
73|    const jy = y + (r() - 0.5) * 18 * layer;
74|    return {
75|      d: blobPath(jx, jy, rad * (layer ? 0.7 : 1), r),
76|      stroke: "none",
77|      width: 0,
78|      opacity: layer ? 0.35 : 0.6,
79|      fill: c,
80|      blurred: true,
81|    };
82|  });
83|}
84|
85|const INK_REGIONS: [Pt[], number, number][] = [
86|  [R.roof, -35, 6], [R.ground, 8, 9], [R.wall, 70, 10], [R.sky, -12, 16],
87|];
88|
89|function inkLayer(layer: number): DrawStroke[] {
90|  if (layer === 0) {
91|    return CONTOURS.map((k) => ({
92|      d: C[k],
93|      stroke: BLUE,
94|      width: k === "funnel" ? 2.2 : 1.8,
95|      opacity: 1,
96|    }));
97|  }
98|  const r = rng(9 + layer);
99|  const fallback: [Pt[], number, number] = [R.ground, 8, 9];
100|  const [poly, deg, gap] = INK_REGIONS[(layer - 1) % INK_REGIONS.length] ?? fallback;
101|  return [{
102|    d: zigzag(hatch(poly, deg, gap, 2, r)),
103|    stroke: BLUE,
104|    width: 1.1,
105|    opacity: 0.55,
106|  }];
107|}
108|
109|// Layer 0 is the outline pass; higher layers cycle shading/wash depth.
110|export function strokesForSkin(skin: PictureSkin, layer: number): DrawStroke[] {
111|  if (skin === "pencil" || skin === "comic" || skin === "chihiro") return extraLayer(skin, layer);
112|  if (skin === "watercolor") return watercolorLayer(layer);
113|  if (skin === "ink") return inkLayer(layer);
114|  return engravingLayer(layer);
115|}
116|
117|const STILL_SPOTS: [number, number, string, number][] = [
118|  [70, 70, "#9FC4FF", 46], [160, 56, "#C9DDF7", 52],
119|  [150, 246, "#E6C27A", 44], [150, 190, "#C9785A", 36],
120|  [200, 322, "#B9C98A", 52],
121|];
122|
123|export function stillStrokes(skin: PictureSkin): DrawStroke[] {
124|  if (skin === "pencil" || skin === "comic" || skin === "chihiro") return extraStill(skin);
125|  if (skin === "watercolor") {
126|    const r = rng(2);
127|    return STILL_SPOTS.map(([x, y, c, rad]) => ({
128|      d: blobPath(x, y, rad, r),
129|      stroke: "none",
130|      width: 0,
131|      opacity: 0.6,
132|      fill: c,
133|      blurred: true,
134|    }));
135|  }
136|  const out: DrawStroke[] = [];
137|  if (skin === "engraving") {
138|    out.push({ d: OVAL, stroke: INK, width: 1.1, opacity: 1 });
139|  }
140|  const color = skin === "engraving" ? INK : BLUE;
141|  for (const k of CONTOURS) out.push({ d: C[k], stroke: color, width: 1.4, opacity: 0.9 });
142|  return out;
143|}
