97|// Passes accumulate: time only reveals more strokes and appends layers,
98|// so a drawn stroke never returns to hidden.
99|test("drawing passes accumulate and never wipe", () => {
100|  let now = 1000;
101|  vi.spyOn(performance, "now").mockImplementation(() => now);
102|  const queue: FrameRequestCallback[] = [];
103|  vi.stubGlobal("requestAnimationFrame", (cb: FrameRequestCallback) => {
104|    queue.push(cb);
105|    return queue.length;
106|  });
107|  vi.stubGlobal("matchMedia", () => ({
108|    matches: false,
109|    addEventListener: () => {},
110|    removeEventListener: () => {},
111|  }));
112|  const host = document.createElement("div");
113|  document.body.appendChild(host);
114|  const root = createRoot(host);
115|  act(() => {
116|    root.render(<Harness card={{ phase: "loading" }} />);
117|  });
118|  const dash = () =>
119|    [...host.querySelectorAll("svg.picdraw-art path")].map(
120|      (p) => (p as SVGPathElement).style.strokeDashoffset,
121|    );
122|  const step = (n: number) => {
123|    act(() => {
124|      for (let i = 0; i < n && queue.length > 0; i++) {
125|        now += 32;
126|        queue.splice(0).forEach((cb) => cb(now));
127|      }
128|    });
129|  };
130|  step(120);
131|  const pathsFirst = dash().length;
132|  const first = dash().filter((d) => d === "0").length;
133|  expect(first).toBeGreaterThan(0);
134|  const snap = dash();
135|  step(3000);
136|  const later = dash();
137|  expect(later.filter((d) => d === "0").length).toBeGreaterThanOrEqual(first);
138|  expect(later.length).toBeGreaterThanOrEqual(pathsFirst);
139|  snap.forEach((d, i) => {
140|    if (d === "0") expect(later[i]).toBe("0");
141|  });
142|  act(() => {
143|    root.unmount();
144|  });
145|});
