184|// A cached revisit swaps ready urls without passing through loading: the
185|// new image must wait for its own load, never flash as revealed. The
186|// probe records every render, so an effect-only reset still shows the
187|// one frame where the new url reads as loaded.
188|test("a ready url swap never shows the new image as revealed", () => {
189|  const raf = vi.fn(() => 0);
190|  stubEnv(raf);
191|  const seen: { url: string; loaded: boolean }[] = [];
192|  let mark: () => void = () => {};
193|  function LoadedProbe({ url }: { url: string }) {
194|    const { loaded, markLoaded } = usePictureLoaded(url);
195|    mark = markLoaded;
196|    seen.push({ url, loaded });
197|    return null;
198|  }
199|  const host = document.createElement("div");
200|  document.body.appendChild(host);
201|  const root = createRoot(host);
202|  act(() => {
203|    root.render(<LoadedProbe url="https://img/a.jpg" />);
204|  });
