1|// One slot for a picture on its way: the skin drawing runs while it
2|// loads, freezes the moment the url is ready, and stays under the image
3|// until the image has loaded. Then the skin reveal plays over the paper.
4|"use client";
5|
6|import type { ImgHTMLAttributes } from "react";
7|import { PictureDraw, usePictureLoaded } from "./picture-draw";
8|import { usePictureSkin } from "./picture-skin";
9|
10|type SlotImgProps = Omit<ImgHTMLAttributes<HTMLImageElement>, "src" | "alt" | "onLoad" | "onError">;
11|
12|export function PictureSlot({
13|  phase,
14|  url,
15|  alt,
16|  className,
17|  imgProps,
18|}: {
19|  phase: "loading" | "ready";
20|  url: string;
21|  alt: string;
22|  className: string;
23|  imgProps?: SlotImgProps;
24|}) {
25|  const skin = usePictureSkin();
26|  const ready = phase === "ready";
27|  const { loaded, imgRef, markLoaded } = usePictureLoaded(ready ? url : "");
28|  const { className: imgClass, ...rest } = imgProps ?? {};
29|  return (
30|    <div className={className} role={ready ? undefined : "status"} data-picture-skin={skin}>
31|      {ready && loaded ? null : (
32|        <div className="pic-under">
33|          <PictureDraw skin={skin} frozen={ready} />
34|        </div>
35|      )}
36|      {ready ? (
37|        <img
38|          {...rest}
39|          ref={imgRef}
40|          onLoad={markLoaded}
41|          onError={markLoaded}
42|          className={`pic-img ${imgClass ?? ""} ${loaded ? `rv-${skin}` : "pic-waiting"}`}
43|          src={url}
44|          alt={alt}
45|        />
46|      ) : null}
47|    </div>
48|  );
49|}

